1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: base premiums for main items ---
6	  it("quotes an empty item list — premium 5 G (processing fee only)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("quotes a plain sword for a new customer — 100 G base + 10 G first insurance + 5 G fee = 115 G");
15	  it.todo("quotes a plain amulet for a new customer — 60 G base + 6 G first insurance + 5 G fee = 71 G");
16	  it.todo("quotes a plain staff for a new customer — 80 G base + 8 G first insurance + 5 G fee = 93 G");
17	  it.todo("quotes a plain potion for a new customer — 40 G base + 4 G first insurance + 5 G fee = 49 G");
18	
19	  // --- Quote: components and the block of 3 alike ---
20	  it.todo("quotes 1 rune — 25 G base premium");
21	  it.todo("quotes 2 runes — 50 G base premium (no block)");
22	  it.todo("quotes 3 runes — 60 G base premium (block applies)");
23	  it.todo("quotes 4 runes — 100 G base premium (no block — block requires exactly 3)");
24	  it.todo("quotes 7 runes — 175 G base premium");
25	  it.todo("quotes 2 runes + 1 moonstone — 75 G base premium (no block: different types)");
26	  it.todo("quotes 3 runes + 3 moonstones — 120 G base premium (two separate blocks)");
27	
28	  // --- Quote: item-specific modifiers ---
29	  it.todo("adds a 50 % curse surcharge to a cursed sword — 100 G base + 50 G curse");
30	  it.todo("adds a 30 % high-enchantment surcharge to a sword with enchantment 5");
31	  it.todo("adds no high-enchantment surcharge to a sword with enchantment 4");
32	  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
33	
34	  // --- Quote: policy-wide modifiers ---
35	  it.todo("applies the 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
36	  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
37	  it.todo("applies the 10 % first insurance surcharge to the policy base premium");
38	  it.todo("applies the 15 % follow-up discount to every contract after the customer's first");
39	  it.todo("adds the 5 G processing fee at the very end of every premium");
40	
41	  // --- Quote: modifier scope on multi-item policies ---
42	  it.todo("applies the curse surcharge only to the cursed item's base premium — cursed sword + plain amulet → 160 G base + 50 G curse");
43	
44	  // --- Quote: rounding in MHPCO's favour ---
45	  it.todo("rounds a premium of 197.5 G up to 198 G");
46	  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");
47	
48	  // --- Quote: integration examples ---
49	  it.todo("quotes a newcomer's cursed sword (steel, enchantment 3) — 165 G");
50	  it.todo("quotes a 3-year customer's second contract for a cursed sword with enchantment 7 — 160 G");
51	
52	  // --- Quote: errors ---
53	  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick)");
54	
55	  // --- Claim: standard reimbursement ---
56	  it.todo("pays a regular sword (steel, enchantment 3) with damage 500 G — payout 400 G (damage minus 100 G deductible)");
57	  it.todo("pays damage 200 G to a rune — payout 100 G (runes have no enchantment or material)");
58	
59	  // --- Claim: special clauses ---
60	  it.todo("reimburses damage to an item with enchantment 8 at 50 % — dragon sword, damage 1000 G → payout 400 G");
61	  it.todo("fully reimburses dragon-material damage — dragon sword, enchantment 5, damage 800 G → payout 700 G");
62	  it.todo("lets the 50 % rule win when both clauses apply — dragon sword, enchantment 9, damage 1000 G → payout 400 G");
63	  it.todo("applies only the high-enchantment clause to a steel sword with enchantment 9, damage 1000 G → payout 400 G");
64	
65	  // --- Claim: deductible per damage event ---
66	  it.todo("applies the 100 G deductible once per damaged item — sword 500 G + amulet 300 G → payout 600 G");
67	
68	  // --- Claim: insurance sum and cap ---
69	  it.todo("caps a policy at twice the insurance sum — sword + amulet → insurance sum 1600 G, cap 3200 G");
70	  it.todo("bases the cap on unmodified insurance values — cursed sword → cap 2000 G despite premium modifiers");
71	  it.todo("bases the insurance sum on full component values — sword + 3 runes → insurance sum 1750 G despite the block discount");
72	  it.todo("reduces a payout to the remaining cap across successive claims — two 1500 G claims on a sword → 1400 G then 600 G");
73	  it.todo("reports the remaining cap after each claim");
74	
75	  // --- Claim: multiple items of the same type ---
76	  it.todo("insures two swords — insurance sum 2000 G, cap 4000 G");
77	  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
78	  it.todo("rejects a claim with more damage entries of a type than the policy covers");
79	
80	  // --- Claim: rounding ---
81	  it.todo("rounds a payout of 350.5 G down to 350 G");
82	
83	  // --- Claim: errors ---
84	  it.todo("rejects a claim whose damage references an item not covered by the policy");
85	  it.todo("rejects a claim whose damage references an unknown item type");
86	  it.todo("rejects a claim containing a damage entry with a negative amount");
87	
88	  // --- Scenario / CLI wiring ---
89	  it.todo("returns one result per step, in order, for a mixed quote-and-claim scenario");
90	});
